const ThemeContext = createContext("light")

function ThemeName() {
  return <span>{useContext(ThemeContext)}</span>
}

import { useSearchParams } from "react-router-dom"
function Search() {
  const [params, setParams] = useSearchParams()
  const query = params.get("q") ?? ""
  return <label>Поиск<input value={query} onChange={event => {
    const next = new URLSearchParams(params)
    next.set("q", event.target.value); next.delete("page")
    setParams(next, { replace: true })
  }} /></label>
}

function createRequestSnapshot(session) {
  return { user: { id: session.user.id, name: session.user.name } }
}
